  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #eef2f7;
      --surface: #ffffff;
      --surface-muted: #f8fafc;
      --text: #111827;
      --muted: #5b6575;
      --border: #d9e0ea;
      --danger: #c81e1e;
