      left: 1rem;
      top: 1rem;
      z-index: 10;
      transform: translateY(-150%);
      border-radius: 999px;
      background: var(--text);
      color: #ffffff;
      padding: 0.75rem 1rem;
      text-decoration: none;
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .app-shell {
      width: min(1120px, 100%);
      margin: 0 auto;
      padding: 32px 20px 56px;
    }

    .site-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 28px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      color: var(--muted);
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      display: grid;
      width: 42px;
      height: 42px;
      place-items: center;
      border-radius: 14px;
      background: #111827;
      color: #ffffff;
      font-size: 1.2rem;
    }

    .layout {
      display: grid;
      grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.6fr);
      gap: 24px;
      align-items: start;
    }

    .preview-card,
    .details-card {
      border: 1px solid rgba(217, 224, 234, 0.78);
      border-radius: var(--radius-lg);
      background: rgba(255, 255, 255, 0.86);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .preview-card {
      overflow: hidden;
    }

    .hero-image {
      display: block;
      width: 100%;
      aspect-ratio: 16 / 10;
      object-fit: cover;
      background: #dbeafe;
    }

    .image-actions {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 20px;
      background: var(--surface);
    }

    .caption {
      margin: 0;
      color: var(--muted);
      line-height: 1.5;
    }

    .details-card {
      padding: 28px;
    }

    .eyebrow {
      margin: 0 0 12px;
      color: var(--accent);
      font-size: 0.8rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1,
    h2 {
      margin: 0;
      line-height: 1.1;
    }

    h1 {
      max-width: 11ch;
      font-size: clamp(2.5rem, 7vw, 5.25rem);
      letter-spacing: -0.07em;
    }

    .details-card p {
      color: var(--muted);
      line-height: 1.65;
    }

    .metadata {
      display: grid;
      gap: 12px;
      margin: 24px 0 0;
      padding: 0;
      list-style: none;
    }

    .metadata li {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      border-top: 1px solid var(--border);
      padding-top: 12px;
      color: var(--muted);
    }

    .metadata strong {
      color: var(--text);
      font-weight: 700;
    }

    .button {
      display: inline-flex;
      min-height: 44px;
      align-items: center;
      justify-content: center;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.75rem 1.15rem;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:focus-visible,
    .skip-link:focus-visible,
    dialog:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .button-danger {
      background: var(--danger);
      color: #ffffff;
      box-shadow: 0 12px 24px rgba(200, 30, 30, 0.24);
    }

    .button-danger:hover {
      background: var(--danger-hover);
    }

    .button-secondary {
      border-color: var(--border);
      background: #ffffff;
      color: var(--text);
    }

    .button-secondary:hover {
      background: var(--surface-muted);
    }

    dialog {
      width: min(92vw, 460px);
      border: 0;
      border-radius: 24px;
      padding: 0;
      background: transparent;
      color: inherit;
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.55);
      backdrop-filter: blur(8px);
    }

    .dialog-card {
      max-height: min(85vh, 560px);
      overflow: auto;
      border: 1px solid rgba(255, 255, 255, 0.65);
      border-radius: 24px;
      background: var(--surface);
      box-shadow: var(--shadow);
      padding: 28px;
    }

    .dialog-icon {
      display: grid;
      width: 52px;
      height: 52px;
      place-items: center;
      margin-bottom: 18px;
      border-radius: 18px;
      background: #fee2e2;
      color: var(--danger);
      font-size: 1.6rem;
      font-weight: 900;
    }

    .dialog-card h2 {
      font-size: clamp(1.5rem, 6vw, 2rem);
      letter-spacing: -0.04em;
    }

    .dialog-card p {
      margin: 12px 0 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 26px;
    }

    .status {
      min-height: 1.5em;
      margin: 16px 0 0;
      color: var(--muted);
      font-weight: 700;
    }

    .is-deleted .preview-card {
      opacity: 0.48;
      filter: grayscale(0.9);
    }

    .is-deleted .trigger {
      cursor: not-allowed;
      opacity: 0.68;
    }

    @media (max-width: 760px) {
      .site-header,
      .image-actions,
      .dialog-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .layout {
        grid-template-columns: 1fr;
      }

      .button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      .preview-card,
      .details-card,
      .dialog-card,
      .button {
        border: 1px solid ButtonText;
      }

      .button:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid Highlight;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="root"></div>

  <script>
    const previewSvg = `
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1400 875">
        <defs>
          <linearGradient id="sky" x1="0" x2="0" y1="0" y2="1">
            <stop stop-color="#dbeafe"/>
            <stop offset=".58" stop-color="#f8fafc"/>
            <stop offset="1" stop-color="#93c5fd"/>
          </linearGradient>
          <linearGradient id="mountain" x1="0" x2="1">
            <stop stop-color="#1e3a8a"/>
            <stop offset="1" stop-color="#111827"/>
          </linearGradient>
        </defs>
        <rect width="1400" height="875" fill="url(#sky)"/>
        <circle cx="1110" cy="155" r="82" fill="#fef3c7"/>
        <path d="M0 540 260 220l168 198 178-268 250 316 190-214 354 288v335H0z" fill="url(#mountain)"/>
        <path d="M250 233 337 336 422 210l77 97-79-42-58 99-42-73z" fill="#f8fafc" opacity=".85"/>
        <path d="M0 606c165-42 295-43 455 0s291 45 448 0 319-42 497 0v269H0z" fill="#1d4ed8" opacity=".55"/>
        <path d="M0 682c177-28 334-16 485 22 191 48 337 43 524-1 145-34 266-43 391-18v190H0z" fill="#0f172a" opacity=".18"/>
      </svg>
    `;

    const image = {
      title: 'Alpine Lake at Dawn',
      collection: 'Travel Library',
      size: '4.8 MB',
      dimensions: '2400 x 1600',
      src: `data:image/svg+xml,${encodeURIComponent(previewSvg)}`,
      alt: 'A calm mountain lake reflecting forested peaks at sunrise.'
    };

    function Header() {
      return `
        <header class="site-header">
          <div class="brand" aria-label="Lumina Library">
            <span class="brand-mark" aria-hidden="true">L</span>
            <span>Lumina Library</span>
          </div>
        </header>
      `;
    }

    function ImagePreview({ image }) {
      return `
        <section class="preview-card" aria-labelledby="preview-heading">
          <img class="hero-image" src="${image.src}" alt="${image.alt}">
          <div class="image-actions">
            <div>
              <h2 id="preview-heading">${image.title}</h2>
              <p class="caption">Previewing a saved image from your personal library.</p>
            </div>
            <button class="button button-danger trigger" type="button" id="delete-trigger">
              Delete image
            </button>
          </div>
        </section>
      `;
    }

    function ImageDetails({ image }) {
      return `
        <aside class="details-card" aria-labelledby="page-title">
          <p class="eyebrow">${image.collection}</p>
          <h1 id="page-title">Image preview</h1>
          <p>
            Review this image before deciding whether to keep it in your library.
            Deleting it removes the file from this collection.
          </p>
          <ul class="metadata" aria-label="Image details">
            <li><span>File size</span><strong>${image.size}</strong></li>
            <li><span>Dimensions</span><strong>${image.dimensions}</strong></li>
            <li><span>Status</span><strong id="image-status">Saved</strong></li>
          </ul>
          <p class="status" id="status-message" tabindex="-1" aria-live="polite"></p>
        </aside>
      `;
    }

    function DeleteDialog({ image }) {
      return `
        <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
          <div class="dialog-card">
            <div class="dialog-icon" aria-hidden="true">!</div>
            <h2 id="dialog-title">Delete this image?</h2>
            <p id="dialog-description">
              Are you sure you want to delete "${image.title}" from your library?
              This action cannot be undone.
            </p>
            <div class="dialog-actions">
              <button class="button button-secondary" type="button" id="cancel-delete">
                Cancel
              </button>
              <button class="button button-danger" type="button" id="confirm-delete">
                Delete image
              </button>
            </div>
          </div>
        </dialog>
      `;
    }

    function App() {
      return `
        <div class="app-shell">
          ${Header()}
          <main id="main-content" class="layout">
            ${ImagePreview({ image })}
            ${ImageDetails({ image })}
          </main>
        </div>
        ${DeleteDialog({ image })}
      `;
    }

    function bindDialogBehavior() {
      const dialog = document.getElementById('delete-dialog');
      const trigger = document.getElementById('delete-trigger');
      const cancelButton = document.getElementById('cancel-delete');
      const confirmButton = document.getElementById('confirm-delete');
      const statusMessage = document.getElementById('status-message');
      const imageStatus = document.getElementById('image-status');
      let imageDeleted = false;

      trigger.addEventListener('click', () => {
        if (imageDeleted) {
          return;
        }

        dialog.showModal();
        document.body.classList.add('modal-open');
        cancelButton.focus();
      });

      cancelButton.addEventListener('click', () => {
        dialog.close('cancel');
      });

      confirmButton.addEventListener('click', () => {
        imageDeleted = true;
        document.body.classList.add('is-deleted');
        imageStatus.textContent = 'Deleted';
        statusMessage.textContent = 'The image was deleted from your library.';
        trigger.disabled = true;
        trigger.textContent = 'Image deleted';
        dialog.close('delete');
      });

      dialog.addEventListener('close', () => {
        document.body.classList.remove('modal-open');

        if (dialog.returnValue === 'delete') {
          statusMessage.focus();
        }
      });
    }

    document.getElementById('root').innerHTML = App();
    bindDialogBehavior();
  </script>
</body>
</html>
