const path = require('path');
const { chromium } = require('playwright');

const axePath = require.resolve('axe-core/axe.min.js');
const htmlPath = path.resolve('index.html');
const url = 'file://' + htmlPath;

function summarize(violations) {
  return violations.map(v => ({
    id: v.id,
    impact: v.impact,
    tags: v.tags,
    targets: v.nodes.map(n => n.target)
  }));
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto(url, { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });

  const defaultClosed = await page.locator('#delete-dialog').evaluate(el => !el.open);
  const triggerClass = await page.locator('#delete-trigger').evaluate(el => el.classList.contains('trigger'));
  const initial = await page.evaluate(async () => await window.axe.run(document, { resultTypes: ['violations'] }));

  await page.click('#delete-trigger');
  const openAndFocused = await page.evaluate(() => {
    const dialog = document.getElementById('delete-dialog');
    const cancel = document.getElementById('cancel-delete');
    return dialog.open && document.activeElement === cancel;
  });
  const modal = await page.evaluate(async () => await window.axe.run(document, { resultTypes: ['violations'] }));
  await browser.close();

  const wcag = [...initial.violations, ...modal.violations]
    .filter(v => !v.tags.includes('best-practice'));
  const result = {
    defaultClosed,
    triggerClass,
    openAndFocused,
    initial: summarize(initial.violations),
    modal: summarize(modal.violations),
    wcag: summarize(wcag)
  };
  console.log(JSON.stringify(result, null, 2));
  if (!defaultClosed || !triggerClass || !openAndFocused || wcag.length) process.exit(1);
})();
