<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="root"></div>

  <script>
    const previewSvg = `
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1400 875">
        <defs>
          <linearGradient id="sky" x1="0" x2="0" y1="0" y2="1">
            <stop stop-color="#dbeafe"/>
            <stop offset=".58" stop-color="#f8fafc"/>
            <stop offset="1" stop-color="#93c5fd"/>
          </linearGradient>
          <linearGradient id="mountain" x1="0" x2="1">
            <stop stop-color="#1e3a8a"/>
            <stop offset="1" stop-color="#111827"/>
          </linearGradient>
        </defs>
        <rect width="1400" height="875" fill="url(#sky)"/>
        <circle cx="1110" cy="155" r="82" fill="#fef3c7"/>
        <path d="M0 540 260 220l168 198 178-268 250 316 190-214 354 288v335H0z" fill="url(#mountain)"/>
        <path d="M250 233 337 336 422 210l77 97-79-42-58 99-42-73z" fill="#f8fafc" opacity=".85"/>
        <path d="M0 606c165-42 295-43 455 0s291 45 448 0 319-42 497 0v269H0z" fill="#1d4ed8" opacity=".55"/>
        <path d="M0 682c177-28 334-16 485 22 191 48 337 43 524-1 145-34 266-43 391-18v190H0z" fill="#0f172a" opacity=".18"/>
      </svg>
    `;

    const image = {
      title: 'Alpine Lake at Dawn',
      collection: 'Travel Library',
      size: '4.8 MB',
      dimensions: '2400 x 1600',
      src: `data:image/svg+xml,${encodeURIComponent(previewSvg)}`,
      alt: 'A calm mountain lake reflecting forested peaks at sunrise.'
    };

    function Header() {
      return `
        <header class="site-header">
          <div class="brand">
            <span class="brand-mark" aria-hidden="true">L</span>
            <span>Lumina Library</span>
          </div>
        </header>
      `;
    }

    function ImagePreview({ image }) {
      return `
        <section class="preview-card" aria-labelledby="preview-heading">
          <img class="hero-image" src="${image.src}" alt="${image.alt}">
          <div class="image-actions">
            <div>
              <h2 id="preview-heading">${image.title}</h2>
              <p class="caption">Previewing a saved image from your personal library.</p>
            </div>
            <button class="button button-danger trigger" type="button" id="delete-trigger">
              Delete image
            </button>
          </div>
        </section>
      `;
    }

    function ImageDetails({ image }) {
      return `
        <aside class="details-card" aria-labelledby="details-heading">
          <p class="eyebrow">${image.collection}</p>
          <h2 id="details-heading">Image details</h2>
          <p>
            Review this image before deciding whether to keep it in your library.
            Deleting it removes the file from this collection.
          </p>
          <ul class="metadata" aria-label="Image details">
            <li><span>File size</span><strong>${image.size}</strong></li>
            <li><span>Dimensions</span><strong>${image.dimensions}</strong></li>
            <li><span>Status</span><strong id="image-status">Saved</strong></li>
          </ul>
          <p class="status" id="status-message" tabindex="-1" aria-live="polite"></p>
        </aside>
      `;
    }

    function DeleteDialog({ image }) {
      return `
        <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
          <div class="dialog-card">
            <div class="dialog-icon" aria-hidden="true">!</div>
            <h2 id="dialog-title">Delete this image?</h2>
            <p id="dialog-description">
              Are you sure you want to delete "${image.title}" from your library?
              This action cannot be undone.
            </p>
            <div class="dialog-actions">
              <button class="button button-secondary" type="button" id="cancel-delete">
                Cancel
              </button>
              <button class="button button-danger" type="button" id="confirm-delete">
                Delete image
              </button>
            </div>
          </div>
        </dialog>
      `;
    }

    function App() {
      return `
        <div class="app-shell">
          ${Header()}
          <main id="main-content" tabindex="-1">
            <section class="intro" aria-labelledby="page-title">
              <p class="eyebrow">${image.collection}</p>
              <h1 id="page-title">Image preview</h1>
              <p>Inspect your saved image and choose whether it should stay in your personal library.</p>
            </section>
            <div class="layout">
              ${ImagePreview({ image })}
              ${ImageDetails({ image })}
            </div>
          </main>
        </div>
        ${DeleteDialog({ image })}
      `;
    }

    function bindDialogBehavior() {
      const dialog = document.getElementById('delete-dialog');
      const trigger = document.getElementById('delete-trigger');
      const cancelButton = document.getElementById('cancel-delete');
      const confirmButton = document.getElementById('confirm-delete');
      const statusMessage = document.getElementById('status-message');
      const imageStatus = document.getElementById('image-status');
      let imageDeleted = false;

      trigger.addEventListener('click', () => {
        if (imageDeleted) {
          return;
        }

        dialog.showModal();
        document.body.classList.add('modal-open');
        cancelButton.focus();
      });

      cancelButton.addEventListener('click', () => {
        dialog.close('cancel');
      });

      confirmButton.addEventListener('click', () => {
        imageDeleted = true;
        document.body.classList.add('is-deleted');
        imageStatus.textContent = 'Deleted';
        statusMessage.textContent = 'The image was deleted from your library.';
        trigger.disabled = true;
        trigger.textContent = 'Image deleted';
        dialog.close('delete');
      });

      dialog.addEventListener('close', () => {
        document.body.classList.remove('modal-open');

        if (dialog.returnValue === 'delete') {
          statusMessage.focus();
        }
      });
    }

    document.getElementById('root').innerHTML = App();
    bindDialogBehavior();
  </script>
</body>
</html>
