      border-radius: 999px;
      background: var(--text);
      color: #ffffff;
      padding: 0.75rem 1rem;
      text-decoration: none;
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .app-shell {
      width: min(1120px, 100%);
      margin: 0 auto;
      padding: 32px 20px 56px;
    }

    .site-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 28px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      color: var(--muted);
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      display: grid;
      width: 42px;
      height: 42px;
      place-items: center;
      border-radius: 14px;
      background: #111827;
      color: #ffffff;
      font-size: 1.2rem;
    }

    .layout {
      display: grid;
      grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.6fr);
      gap: 24px;
      align-items: start;
