      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 20px;
      background: var(--surface);
    }

    .caption {
      margin: 0;
      color: var(--muted);
      line-height: 1.5;
    }

    .details-card {
      padding: 28px;
    }

    .eyebrow {
      margin: 0 0 12px;
