     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       z-index: 10;
       transform: translateY(-150%);
       border-radius: 999px;
       background: var(--text);
       color: #ffffff;
       padding: 0.75rem 1rem;
       text-decoration: none;
       transition: transform 160ms ease;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .app-shell {
       width: min(1120px, 100%);
       margin: 0 auto;
       padding: 32px 20px 56px;
     }

     .site-header {
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 1rem;
       margin-bottom: 28px;
     }

     .brand {
       display: inline-flex;
       align-items: center;
       gap: 0.75rem;
       color: var(--muted);
       font-weight: 700;
       letter-spacing: 0.02em;
     }

     .brand-mark {
       display: grid;
       width: 42px;
       height: 42px;
       place-items: center;
       border-radius: 14px;
       background: #111827;
       color: #ffffff;
       font-size: 1.2rem;
     }

     .layout {
       display: grid;
       grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.6fr);
       gap: 24px;
       align-items: start;
     }

     .preview-card,
     .details-card {
       border: 1px solid rgba(217, 224, 234, 0.78);
       border-radius: var(--radius-lg);
       background: rgba(255, 255, 255, 0.86);
       box-shadow: var(--shadow);
       backdrop-filter: blur(18px);
     }

     .preview-card {
       overflow: hidden;
     }

     .hero-image {
       display: block;
       width: 100%;
       aspect-ratio: 16 / 10;
       object-fit: cover;
       background: #dbeafe;
     }

     .image-actions {
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 1rem;
       padding: 20px;
       background: var(--surface);
     }

     .caption {
       margin: 0;
       color: var(--muted);
       line-height: 1.5;
     }

     .details-card {
       padding: 28px;
     }

     .eyebrow {
       margin: 0 0 12px;
       color: var(--accent);
       font-size: 0.8rem;
       font-weight: 800;
       letter-spacing: 0.12em;
       text-transform: uppercase;
