       border-top: 1px solid var(--border);
       padding-top: 12px;
       color: var(--muted);
     }

     .metadata strong {
       color: var(--text);
       font-weight: 700;
     }

     .button {
       display: inline-flex;
       min-height: 44px;
       align-items: center;
       justify-content: center;
       border: 1px solid transparent;
       border-radius: 999px;
       padding: 0.75rem 1.15rem;
       font: inherit;
       font-weight: 800;
       cursor: pointer;
       transition: background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
     }

     .button:hover {
       transform: translateY(-1px);
     }

     .button:focus-visible,
     .skip-link:focus-visible,
     dialog:focus-visible {
       outline: 3px solid var(--accent);
       outline-offset: 3px;
     }

     .button-danger {
       background: var(--danger);
       color: #ffffff;
       box-shadow: 0 12px 24px rgba(200, 30, 30, 0.24);
     }

     .button-danger:hover {
       background: var(--danger-hover);
     }

     .button-secondary {
       border-color: var(--border);
       background: #ffffff;
       color: var(--text);
     }

     .button-secondary:hover {
       background: var(--surface-muted);
     }

     dialog {
       width: min(92vw, 460px);
       border: 0;
       border-radius: 24px;
       padding: 0;
       background: transparent;
       color: inherit;
     }

     dialog::backdrop {
       background: rgba(15, 23, 42, 0.55);
       backdrop-filter: blur(8px);
     }

     .dialog-card {
       max-height: min(85vh, 560px);
       overflow: auto;
       border: 1px solid rgba(255, 255, 255, 0.65);
       border-radius: 24px;
       background: var(--surface);
       box-shadow: var(--shadow);
       padding: 28px;
     }

     .dialog-icon {
       display: grid;
       width: 52px;
       height: 52px;
       place-items: center;
       margin-bottom: 18px;
       border-radius: 18px;
       background: #fee2e2;
       color: var(--danger);
       font-size: 1.6rem;
       font-weight: 900;
     }

     .dialog-card h2 {
       font-size: clamp(1.5rem, 6vw, 2rem);
       letter-spacing: -0.04em;
     }

     .dialog-card p {
       margin: 12px 0 0;
       color: var(--muted);
       line-height: 1.6;
     }

     .dialog-actions {
       display: flex;
       flex-wrap: wrap;
       justify-content: flex-end;
       gap: 12px;
       margin-top: 26px;
     }

     .status {
       min-height: 1.5em;
       margin: 16px 0 0;
       color: var(--muted);
       font-weight: 700;
     }

     .status:focus {
       border-radius: var(--radius-sm);
       outline: 3px solid var(--accent);
       outline-offset: 4px;
     }

     .is-deleted .preview-card {
       opacity: 0.48;
       filter: grayscale(0.9);
     }

     .is-deleted .trigger {
       cursor: not-allowed;
       opacity: 0.68;
     }

     @media (max-width: 760px) {
       .site-header,
       .image-actions,
       .dialog-actions {
         align-items: stretch;
         flex-direction: column;
       }

       .layout {
         grid-template-columns: 1fr;
       }

       .button {
         width: 100%;
       }
     }

     @media (forced-colors: active) {
       .preview-card,
       .details-card,
       .dialog-card,
       .button {
         border: 1px solid ButtonText;
       }

       .button:focus-visible,
       .skip-link:focus-visible,
       .status:focus {
         outline: 3px solid Highlight;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       *,
